window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5acba33758ce7e9e"]={"versions": [{"id": "FIG-5acba33758ce7e9e", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses im AUTOSAR-E2E-Protokoll (End-to-End Communication Protection), spezifisch für das Profil 11 (E2E Profile 11). Das Diagramm modelliert den Teilschritt „Write CRC“ innerhalb der Routinen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Konnektoren / Aufrufrahmen:</strong>\n<ul class=\"fig-list\"><li><code>E2E_P11Protect()</code> (mit Subaktivitäts-Symbol)\n</li><li><code>E2E_P11Forward()</code> (mit Subaktivitäts-Symbol)\n</li></ul>\n</li><li><strong>Aktion:</strong>\n<ul class=\"fig-list\"><li><code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code>\n</li></ul>\n</li><li><strong>Knoten des Steuerungsflusses:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node, ausgefüllter schwarzer Kreis)\n</li><li>Endknoten (Activity Final Node, konzentrischer Kreis mit Kern)\n</li></ul>\n</li><li><strong>Datenobjekte und Parameter:</strong>\n<ul class=\"fig-list\"><li>Lokale Variable: <code>ComputedCRC</code> (1 Byte groß, <code>uint8</code>)\n</li><li>Konfigurationsstruktur: <code>Config-&gt;CRCOffset</code> (Offset-Angabe in Bits)\n</li><li>Zielpuffer / Nutzdaten-Array: <code>Data[]</code> (Byte-Array)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausgehend vom Startknoten verzweigt der Kontrollfluss sequenziell in die Aktionsstufe <code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code>.\n</li><li>Innerhalb der Aktion wird der vorberechnete 1-Byte-Wert <code>ComputedCRC</code> an die über <code>Config-&gt;CRCOffset / 8</code> adressierte Byte-Position im Datenarray <code>Data</code> geschrieben.\n</li><li>Nach Abschluss des Kopiervorgangs geht der Kontrollfluss direkt in den Aktivitätsendknoten über.\n</li><li>Der Teilschritt wird identisch von beiden übergeordneten Funktionen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code> ausgeführt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung dieses Schritts ist normativ gemäß <code>[PRS_E2E_00514]</code>. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die Bitposition <code>CRCOffset</code> in der Konfiguration muss durch 8 teilbar sein (Byte-Ausrichtung).\n</li><li>Das Datenarray <code>Data</code> muss ausreichend allokiert sein, sodass der Index <code>Config-&gt;CRCOffset / 8</code> innerhalb der gültigen Grenzen (<code>Length</code>) liegt.\n</li><li>Vor dem Schreiben der CRC muss <code>ComputedCRC</code> bereits nach den Regeln von Profil 11 (<code>[PRS_E2E_00513]</code>) berechnet worden sein.\n</li><li>Der Schreibzugriff platziert genau 1 Byte der Prüfsumme ohne Beeinflussung benachbarter Nutzdatenbytes.\n</li></ul>"}, {"id": "FIG-2bb61c513831f537", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses im AUTOSAR-E2E-Protokoll (End-to-End Communication Protection), spezifisch für das Profil 11 (E2E Profile 11). Das Diagramm modelliert den Teilschritt „Write CRC“ innerhalb der Routinen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext-Konnektoren / Aufrufrahmen:</strong>\n<ul class=\"fig-list\"><li><code>E2E_P11Protect()</code> (mit Subaktivitäts-Symbol)\n</li><li><code>E2E_P11Forward()</code> (mit Subaktivitäts-Symbol)\n</li></ul>\n</li><li><strong>Aktion:</strong>\n<ul class=\"fig-list\"><li><code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code>\n</li></ul>\n</li><li><strong>Knoten des Steuerungsflusses:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node, ausgefüllter schwarzer Kreis)\n</li><li>Endknoten (Activity Final Node, konzentrischer Kreis mit Kern)\n</li></ul>\n</li><li><strong>Datenobjekte und Parameter:</strong>\n<ul class=\"fig-list\"><li>Lokale Variable: <code>ComputedCRC</code> (1 Byte groß, <code>uint8</code>)\n</li><li>Konfigurationsstruktur: <code>Config-&gt;CRCOffset</code> (Offset-Angabe in Bits)\n</li><li>Zielpuffer / Nutzdaten-Array: <code>Data[]</code> (Byte-Array)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausgehend vom Startknoten verzweigt der Kontrollfluss sequenziell in die Aktionsstufe <code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code>.\n</li><li>Innerhalb der Aktion wird der vorberechnete 1-Byte-Wert <code>ComputedCRC</code> an die über <code>Config-&gt;CRCOffset / 8</code> adressierte Byte-Position im Datenarray <code>Data</code> geschrieben.\n</li><li>Nach Abschluss des Kopiervorgangs geht der Kontrollfluss direkt in den Aktivitätsendknoten über.\n</li><li>Der Teilschritt wird identisch von beiden übergeordneten Funktionen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code> ausgeführt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung dieses Schritts ist normativ gemäß <code>[PRS_E2E_00514]</code>. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die Bitposition <code>CRCOffset</code> in der Konfiguration muss durch 8 teilbar sein (Byte-Ausrichtung).\n</li><li>Das Datenarray <code>Data</code> muss ausreichend allokiert sein, sodass der Index <code>Config-&gt;CRCOffset / 8</code> innerhalb der gültigen Grenzen (<code>Length</code>) liegt.\n</li><li>Vor dem Schreiben der CRC muss <code>ComputedCRC</code> bereits nach den Regeln von Profil 11 (<code>[PRS_E2E_00513]</code>) berechnet worden sein.\n</li><li>Der Schreibzugriff platziert genau 1 Byte der Prüfsumme ohne Beeinflussung benachbarter Nutzdatenbytes.\n</li></ul>"}], "trans": [{"from": "FIG-5acba33758ce7e9e", "to": "FIG-2bb61c513831f537", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
